from flask import Flask,request,jsonify,render_template_string
import os,requests as req
from datetime import datetime
app=Flask(__name__)
SU=os.environ.get('SUPABASE_URL','')
SK=os.environ.get('SUPABASE_KEY','')
H={'apikey':SK,'Authorization':f'Bearer {SK}','Content-Type':'application/json','Prefer':'return=representation'}
DU="https://smartsolar.net.pk/D8BC38AD6637"
def sg(t,p=''):
    r=req.get(f'{SU}/rest/v1/{t}?{p}',headers=H)
    return r.json() if r.ok else []
def sp(t,d):
    r=req.post(f'{SU}/rest/v1/{t}',headers=H,json=d)
    return r.ok
@app.route('/')
def index():return render_template_string(open('templates/index.html').read() if os.path.exists('templates/index.html') else HTML)
@app.route('/api/log',methods=['POST'])
def log():
    d=request.json or {}
    return jsonify({'ok':sp('readings',{'battery_kwh':d.get('battery_kwh',0),'solar_kwh':d.get('solar_kwh',0),'utility_kwh':d.get('utility_kwh',0),'battery_pct':d.get('battery_pct',0),'load_w':d.get('load_w',0),'notes':d.get('notes','')})})
@app.route('/api/history')
def history():
    rows=sg('readings','order=id.desc&limit=50')
    return jsonify(rows if isinstance(rows,list) else [])
@app.route('/api/summary')
def summary():
    rows=sg('readings','order=id.desc&limit=1000')
    if not isinstance(rows,list) or not rows:return jsonify({'total_solar':0,'total_battery':0,'total_utility':0,'avg_battery_pct':0,'peak_load':0,'record_count':0,'today':{'s':0,'b':0,'u':0}})
    ts=sum(r.get('solar_kwh',0)for r in rows);tb=sum(r.get('battery_kwh',0)for r in rows);tu=sum(r.get('utility_kwh',0)for r in rows)
    ab=sum(r.get('battery_pct',0)for r in rows)/len(rows);pk=max((r.get('load_w',0)for r in rows),default=0)
    td=datetime.now().strftime('%Y-%m-%d');tr=[r for r in rows if str(r.get('ts','')).startswith(td)]
    return jsonify({'total_solar':ts,'total_battery':tb,'total_utility':tu,'avg_battery_pct':ab,'peak_load':pk,'record_count':len(rows),'today':{'s':sum(r.get('solar_kwh',0)for r in tr),'b':sum(r.get('battery_kwh',0)for r in tr),'u':sum(r.get('utility_kwh',0)for r in tr)}})
@app.route('/api/suggest',methods=['POST'])
def suggest():
    d=request.json or {};k=os.environ.get('ANTHROPIC_API_KEY','')
    if not k:return jsonify({'suggestion':'Add ANTHROPIC_API_KEY in Render environment variables.'})
    try:
        r=req.post('https://api.anthropic.com/v1/messages',headers={'x-api-key':k,'anthropic-version':'2023-06-01','content-type':'application/json'},json={'model':'claude-sonnet-4-20250514','max_tokens':800,'messages':[{'role':'user','content':f'48V 6200W inverter Pakistan. Solar:{d.get("solar",0):.1f}kWh Battery:{d.get("battery",0):.1f}kWh Grid:{d.get("utility",0):.1f}kWh Batt:{d.get("battery_level",0):.0f}%. Give top 5 tips: best hours for AC/washing machine/iron, SBU vs SUB timing, how to cut grid to under 15%. Pakistan load shedding context. Be specific.'}]},timeout=30)
        return jsonify({'suggestion':r.json()['content'][0]['text']})
    except Exception as e:return jsonify({'suggestion':f'Error: {e}'})
@app.route('/api/clear',methods=['POST'])
def clear():
    req.delete(f'{SU}/rest/v1/readings?id=gte.0',headers=H);return jsonify({'ok':True})
HTML="""<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solar Monitor</title><script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js"></script><style>*{box-sizing:border-box;margin:0;padding:0}body{background:#07070f;color:#ddd;font-family:monospace;font-size:13px}.h{background:#0c0c18;border-bottom:1px solid #1e1e30;padding:14px 18px;display:flex;align-items:center;gap:12px}.ht{color:#f59e0b;font-size:14px;font-weight:700}.m{padding:16px;max-width:1200px;margin:0 auto}.eg{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:14px}.ec{background:#131320;border:1px solid #1e1e30;border-radius:10px;padding:14px}.ev{font-size:22px;font-weight:700;font-family:monospace}.es{font-size:10px;color:#6b6878;margin-top:4px}.eb{height:4px;background:#1e1e30;border-radius:2px;margin-top:10px}.ebf{height:100%;border-radius:2px;transition:width .6s}.card{background:#131320;border:1px solid #1e1e30;border-radius:10px;padding:16px;margin-bottom:12px}.ct{font-size:9px;color:#6b6878;letter-spacing:.12em;margin-bottom:12px}.tg{display:grid;grid-template-columns:1fr 1fr;gap:8px}.fl{grid-column:1/-1}.lbl{font-size:9px;color:#6b6878;display:block;margin-bottom:4px}.inp{background:#0f0f1a;border:1px solid #1e1e30;color:#ddd;font-family:monospace;font-size:12px;border-radius:6px;padding:7px 10px;width:100%;outline:none}.btn{border:1px solid #1e1e30;color:#6b6878;padding:7px 14px;cursor:pointer;font-family:monospace;font-size:11px;border-radius:6px;background:transparent}.btn:hover{border-color:#f59e0b;color:#f59e0b}.btnp{background:#f59e0b;border-color:#f59e0b;color:#000;font-weight:700}.btnp:hover{background:#d97706}.br{display:flex;gap:8px;margin-top:10px;flex-wrap:wrap}table{width:100%;border-collapse:collapse;font-size:11px}th{text-align:left;padding:6px 8px;font-size:9px;color:#6b6878;border-bottom:1px solid #1e1e30}td{padding:6px 8px;border-bottom:1px solid #181828}.ai{background:#0f0f1a;border:1px solid #1e1e3099;border-radius:8px;padding:12px;font-size:12px;line-height:1.7;white-space:pre-wrap;min-height:60px;max-height:300px;overflow-y:auto}.tabs{display:flex;margin-bottom:12px}.tab{background:transparent;border:1px solid #1e1e30;color:#6b6878;padding:6px 12px;cursor:pointer;font-family:monospace;font-size:10px}.tab:first-child{border-radius:6px 0 0 6px}.tab:last-child{border-radius:0 6px 6px 0}.tab.on{background:#f59e0b;border-color:#f59e0b;color:#000;font-weight:700}.tp{display:none}.tp.on{display:block}.cw{position:relative;height:200px;display:flex;align-items:center;justify-content:center}.cc{position:absolute;text-align:center}.cv{font-size:20px;font-weight:700;color:#f59e0b}.lg{margin-top:12px}.lr{display:flex;justify-content:space-between;padding:5px 0;font-size:11px}.ld{width:10px;height:10px;border-radius:50%}@media(max-width:600px){.eg{grid-template-columns:1fr}.tg{grid-template-columns:1fr}}</style></head><body><div class="h"><span style="font-size:22px">☀</span><div><div class="ht">SOLAR MONITOR</div><div style="font-size:9px;color:#6b6878">aliyar 48V 6200W · <span id="st" style="color:#6b6878">CHECKING...</span></div></div></div><div class="m"><div class="eg"><div class="ec"><div style="font-size:9px;color:#6b6878;letter-spacing:.12em">☀ SOLAR kWh</div><div class="ev" id="sv" style="color:#facc15">0.00</div><div class="es" id="ss">Today: 0.00</div><div class="eb"><div class="ebf" id="sb" style="width:0%;background:#facc15"></div></div></div><div class="ec"><div style="font-size:9px;color:#6b6878;letter-spacing:.12em">🔋 BATTERY kWh</div><div class="ev" id="bv" style="color:#4ade80">0.00</div><div class="es" id="bs">Today: 0.00</div><div class="eb"><div class="ebf" id="bb" style="width:0%;background:#4ade80"></div></div></div><div class="ec"><div style="font-size:9px;color:#6b6878;letter-spacing:.12em">⚡ UTILITY kWh</div><div class="ev" id="uv" style="color:#f87171">0.00</div><div class="es" id="us">Today: 0.00</div><div class="eb"><div class="ebf" id="ub" style="width:0%;background:#f87171"></div></div></div></div><div style="display:grid;grid-template-columns:1fr 300px;gap:12px;margin-bottom:12px"><div class="card"><div class="ct">ENERGY DISTRIBUTION</div><div class="cw"><canvas id="dc" style="max-width:180px;max-height:180px"></canvas><div class="cc"><div class="cv" id="cp">—</div><div style="font-size:9px;color:#6b6878">SOLAR %</div></div></div><div class="lg"><div class="lr"><div style="display:flex;align-items:center;gap:6px"><div class="ld" style="background:#facc15"></div>Solar</div><span id="ls" style="color:#facc15">0%</span></div><div class="lr"><div style="display:flex;align-items:center;gap:6px"><div class="ld" style="background:#4ade80"></div>Battery</div><span id="lb" style="color:#4ade80">0%</span></div><div class="lr"><div style="display:flex;align-items:center;gap:6px"><div class="ld" style="background:#f87171"></div>Utility</div><span id="lu" style="color:#f87171">0%</span></div></div></div><div class="card"><div class="ct">📥 LOG READING</div><div class="tg"><div><label class="lbl">☀ SOLAR kWh</label><input class="inp" id="fs" type="number" step="0.01" placeholder="e.g. 8.5"></div><div><label class="lbl">🔋 BATTERY kWh</label><input class="inp" id="fb" type="number" step="0.01" placeholder="e.g. 3.2"></div><div><label class="lbl">⚡ UTILITY kWh</label><input class="inp" id="fu" type="number" step="0.01" placeholder="e.g. 1.4"></div><div><label class="lbl">🔋 BATTERY %</label><input class="inp" id="fp" type="number" step="1" placeholder="e.g. 75"></div><div class="fl"><label class="lbl">🔌 LOAD (W)</label><input class="inp" id="fl" type="number" step="10" placeholder="e.g. 1200"></div><div class="fl"><label class="lbl">📝 NOTES</label><input class="inp" id="fn" type="text" placeholder="Optional..."></div></div><div class="br"><button class="btn btnp" onclick="logR()">💾 SAVE</button><button class="btn" onclick="clearF()">✕ CLEAR</button></div><div style="font-size:10px;color:#6b6878;margin-top:8px">Read from <a href="https://smartsolar.net.pk/D8BC38AD6637" target="_blank" style="color:#f59e0b">Smart Solar ↗</a></div></div></div><div class="card"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><div class="ct" style="margin:0">🤖 AI SUGGESTIONS</div><button class="btn btnp" onclick="getAI()">⚡ GET TIPS</button></div><div class="ai" id="ai">Click GET TIPS to analyze your data and get personalized advice on timing, inverter settings, and reducing utility usage.</div></div><div class="card"><div class="tabs"><button class="tab on" onclick="showT('hist',this)">≡ HISTORY</button><button class="tab" onclick="showT('live',this)">▶ LIVE</button><button class="tab" onclick="showT('tips',this)">💡 TIPS</button></div><div class="tp on" id="t-hist"><div style="display:flex;justify-content:space-between;margin-bottom:8px"><span id="rc" style="font-size:10px;color:#6b6878">0 records</span><div style="display:flex;gap:6px"><button class="btn" style="font-size:10px;padding:4px 8px" onclick="expCSV()">⬇ CSV</button><button class="btn" style="font-size:10px;padding:4px 8px;color:#f87171" onclick="clearAll()">🗑 CLEAR</button></div></div><div style="overflow-x:auto"><table><thead><tr><th>#</th><th>TIME</th><th style="color:#facc15">☀ kWh</th><th style="color:#4ade80">🔋 kWh</th><th style="color:#f87171">⚡ kWh</th><th>BATT%</th><th>NOTES</th></tr></thead><tbody id="hb"><tr><td colspan="7" style="text-align:center;color:#6b6878;padding:20px">No readings yet</td></tr></tbody></table></div></div><div class="tp" id="t-live"><div style="background:#0f0f1a;border:1px solid #1e1e30;border-radius:8px;overflow:hidden"><div style="padding:7px 12px;border-bottom:1px solid #1e1e30;display:flex;justify-content:space-between;font-size:10px"><span style="color:#f59e0b">● LIVE FEED</span><a href="https://smartsolar.net.pk/D8BC38AD6637" target="_blank" style="color:#6b6878">⎋ Open</a></div><iframe src="https://smartsolar.net.pk/D8BC38AD6637" style="width:100%;height:350px;border:none"></iframe><div style="padding:7px 12px;font-size:10px;color:#6b6878">If blank, tap Open above</div></div></div><div class="tp" id="t-tips"><div style="display:grid;gap:10px"><div style="background:#0f0f1a;border:1px solid #1e1e30;border-radius:8px;padding:12px"><div style="color:#facc15;font-weight:700;margin-bottom:8px">☀ Peak Solar: 09:00–15:00</div><div style="font-size:11px;color:#6b6878;line-height:1.9">Run AC, washing machine, iron, water pump ONLY in this window<br>Charge battery to 100% before 15:00<br>Zero grid needed during these hours</div></div><div style="background:#0f0f1a;border:1px solid #1e1e30;border-radius:8px;padding:12px"><div style="color:#4ade80;font-weight:700;margin-bottom:8px">🔋 Evening 17:00–23:00: Battery Mode</div><div style="font-size:11px;color:#6b6878;line-height:1.9">Fans, lights, TV only — no heavy loads<br>Keep battery above 46V (20%)<br>Inverter: SBU mode (Solar→Battery→Grid)</div></div><div style="background:#0f0f1a;border:1px solid #1e1e30;border-radius:8px;padding:12px"><div style="color:#f87171;font-weight:700;margin-bottom:8px">⚡ Grid: 02:00–05:00 only</div><div style="font-size:11px;color:#6b6878;line-height:1.9">Only charge from grid if battery below 30%<br>Off-peak hours = cheapest units<br>Target: grid under 15% of total</div></div><div style="background:#0f0f1a;border:1px solid #1e1e30;border-radius:8px;padding:12px"><div style="color:#f59e0b;font-weight:700;margin-bottom:8px">🔧 Inverter Settings (48V)</div><div style="font-size:11px;color:#6b6878;line-height:1.9">Output priority: SBU (Solar first)<br>Charger: Solar only (daytime)<br>Low battery cutoff: 46V<br>Bulk charge: 56V · Float: 54V</div></div><div style="background:#0f0f1a;border:1px solid #1e1e30;border-radius:8px;padding:12px"><div style="color:#60a5fa;font-weight:700;margin-bottom:8px">🇵🇰 Load Shedding Strategy</div><div style="font-size:11px;color:#6b6878;line-height:1.9">Before grid cuts: charge battery to 100%<br>Switch to Solar-only mode during cut<br>When grid returns at night: only charge if battery below 40%<br>Clean solar panels every 10–15 days (dust!)</div></div></div></div></div></div><script>let dc=null,hd=[];window.onload=()=>{initD();loadS();loadH();checkSt();setInterval(checkSt,30000)};function checkSt(){fetch('https://smartsolar.net.pk/D8BC38AD6637',{mode:'no-cors',cache:'no-cache'}).then(()=>{document.getElementById('st').textContent='ONLINE';document.getElementById('st').style.color='#4ade80'}).catch(()=>{document.getElementById('st').textContent='OFFLINE';document.getElementById('st').style.color='#f87171'})}function initD(){const c=document.getElementById('dc').getContext('2d');dc=new Chart(c,{type:'doughnut',data:{labels:['Solar','Battery','Utility'],datasets:[{data:[1,1,1],backgroundColor:['#facc15','#4ade80','#f87171'],borderWidth:2,borderColor:'#131320'}]},options:{cutout:'72%',plugins:{legend:{display:false}}}})}function updD(s,b,u){const t=s+b+u||1;const sp=(s/t*100).toFixed(1),bp=(b/t*100).toFixed(1),up=(u/t*100).toFixed(1);dc.data.datasets[0].data=[s||.001,b||.001,u||.001];dc.update();document.getElementById('cp').textContent=sp+'%';document.getElementById('ls').textContent=sp+'%';document.getElementById('lb').textContent=bp+'%';document.getElementById('lu').textContent=up+'%';document.getElementById('sb').style.width=sp+'%';document.getElementById('bb').style.width=bp+'%';document.getElementById('ub').style.width=up+'%'}async function loadS(){try{const r=await fetch('/api/summary'),d=await r.json();document.getElementById('sv').textContent=d.total_solar.toFixed(2);document.getElementById('bv').textContent=d.total_battery.toFixed(2);document.getElementById('uv').textContent=d.total_utility.toFixed(2);document.getElementById('ss').textContent='Today: '+(d.today.s||0).toFixed(2)+' kWh';document.getElementById('bs').textContent='Today: '+(d.today.b||0).toFixed(2)+' kWh | Avg: '+d.avg_battery_pct.toFixed(0)+'%';document.getElementById('us').textContent='Today: '+(d.today.u||0).toFixed(2)+' kWh';updD(d.total_solar,d.total_battery,d.total_utility)}catch(e){}}async function loadH(){try{const r=await fetch('/api/history');hd=await r.json();document.getElementById('rc').textContent=hd.length+' records';const b=document.getElementById('hb');if(!hd.length){b.innerHTML='<tr><td colspan="7" style="text-align:center;color:#6b6878;padding:20px">No readings yet</td></tr>';return}b.innerHTML=hd.map(r=>`<tr><td style="color:#6b6878">${r.id}</td><td style="color:#6b6878;font-size:10px">${(r.ts||'').slice(0,16)}</td><td style="color:#facc15">${(r.solar_kwh||0).toFixed(2)}</td><td style="color:#4ade80">${(r.battery_kwh||0).toFixed(2)}</td><td style="color:#f87171">${(r.utility_kwh||0).toFixed(2)}</td><td>${(r.battery_pct||0).toFixed(0)}%</td><td style="color:#6b6878;font-size:10px">${r.notes||'—'}</td></tr>`).join('')}catch(e){}}async function logR(){const body={solar_kwh:parseFloat(document.getElementById('fs').value)||0,battery_kwh:parseFloat(document.getElementById('fb').value)||0,utility_kwh:parseFloat(document.getElementById('fu').value)||0,battery_pct:parseFloat(document.getElementById('fp').value)||0,load_w:parseFloat(document.getElementById('fl').value)||0,notes:document.getElementById('fn').value};try{await fetch('/api/log',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});clearF();loadS();loadH();alert('✓ Saved!')}catch(e){alert('Error saving')}}function clearF(){['fs','fb','fu','fp','fl','fn'].forEach(id=>document.getElementById(id).value='')}async function getAI(){const ai=document.getElementById('ai');ai.textContent='Analyzing...please wait 15 seconds...';try{const s=await fetch('/api/summary'),d=await s.json();const r=await fetch('/api/suggest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({solar:d.total_solar,battery:d.total_battery,utility:d.total_utility,battery_level:d.avg_battery_pct,peak_load:d.peak_load})});const data=await r.json();ai.textContent=data.suggestion}catch(e){ai.textContent='Error. Check server.'}}function showT(n,btn){document.querySelectorAll('.tp').forEach(p=>p.classList.remove('on'));document.querySelectorAll('.tab').forEach(t=>t.classList.remove('on'));document.getElementById('t-'+n).classList.add('on');btn.classList.add('on')}function expCSV(){const rows=[['ID','Time','Solar','Battery','Utility','Batt%','Notes'],...hd.map(r=>[r.id,r.ts,r.solar_kwh,r.battery_kwh,r.utility_kwh,r.battery_pct,r.notes])];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'}));a.download='solar.csv';a.click()}async function clearAll(){if(!confirm('Delete all?'))return;await fetch('/api/clear',{method:'POST'});loadS();loadH()}</script></body></html>"""
if __name__=='__main__':
    port=int(os.environ.get('PORT',5000))
    app.run(host='0.0.0.0',port=port)
